```python
def encode_shift(s: str):
    """
    Returns encoded string by shifting every alphabetic character by 5 in the alphabet.
    Uppercase and lowercase letters are handled separately.
    Non-alphabetic characters remain unchanged.
    """
    def shift_char(ch):
        if 'a' <= ch <= 'z':
            return chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a"))
        elif 'A' <= ch <= 'Z':
            return chr(((ord(ch) + 5 - ord("A")) % 26) + ord("A"))
        else:
            return ch

    return "".join(shift_char(ch) for ch in s)


def decode_shift(s: str):
    """
    Takes as input string encoded with encode_shift function.
    Returns decoded string, handling both uppercase and lowercase letters.
    Non-alphabetic characters remain unchanged.
    """
    def shift_char(ch):
        if 'a' <= ch <= 'z':
            return chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a"))
        elif 'A' <= ch <= 'Z':
            return chr(((ord(ch) - 5 - ord("A")) % 26) + ord("A"))
        else:
            return ch

    return "".join(shift_char(ch) for ch in s)


